            } else if (finalCatalog < 9500000) {
                insights.push(t('ins_catalog_low'));
            }

            if (finalHealth >= 75) {
                insights.push(t('ins_health_high'));
            } else if (finalHealth < 55) {
                insights.push(t('ins_health_low'));
            }

            return {
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                avgProfit: Math.round(avgProfit),
                catalogGrowth: catalogGrowth + '%',
                finalArtistHealth: finalHealth,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.profit < 0) return window.mySimulation.t('hint_loss');
            if (state.domainState.artistHealth < 50) return window.mySimulation.t('hint_health_low');
            if (state.domainState.cash < 1000000) return window.mySimulation.t('hint_cash_low');
            if (results.liveRev > results.streamingRev + results.publishingRev + results.syncRev) return window.mySimulation.t('hint_live_heavy');
            return null;
        }

